from pydantic import BaseModel, Field
from database import BookStatus

class BookBase(BaseModel):
    title: str = Field(..., min_length=1)
    author: str = Field(..., min_length=1)
    status: BookStatus = BookStatus.TO_READ

class BookCreate(BookBase):
    pass

class BookUpdate(BaseModel):
    title: str | None = None
    author: str | None = None
    status: BookStatus | None = None

class BookResponse(BookBase):
    id: int

    class Config:
        from_attributes = True

from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.middleware.cors import CORSMiddleware
from sqlalchemy.orm import Session
import database as db
import schemas

db.Base.metadata.create_all(bind=db.engine)

app = FastAPI(title="Book Tracker API")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

def get_db():
    database_session = db.SessionLocal()
    try:
        yield database_session
    finally:
        database_session.close()

@app.get("/books", response_model=list[schemas.BookResponse])
def get_books(db_session: Session = Depends(get_db)):
    return db_session.query(db.Book).all()

@app.get("/books/{book_id}", response_model=schemas.BookResponse)
def get_book(book_id: int, db_session: Session = Depends(get_db)):
    book = db_session.query(db.Book).filter(db.Book.id == book_id).first()
    if not book:
        raise HTTPException(status_code=404, detail="Book not found")
    return book

@app.post("/books", response_model=schemas.BookResponse, status_code=status.HTTP_201_CREATED)
def create_book(book: schemas.BookCreate, db_session: Session = Depends(get_db)):
    db_book = db.Book(title=book.title, author=book.author, status=book.status)
    db_session.add(db_book)
    db_session.commit()
    db_session.refresh(db_book)
    return db_book

@app.put("/books/{book_id}", response_model=schemas.BookResponse)
def update_book(book_id: int, book_update: schemas.BookUpdate, db_session: Session = Depends(get_db)):
    db_book = db_session.query(db.Book).filter(db.Book.id == book_id).first()
    if not db_book:
        raise HTTPException(status_code=404, detail="Book not found")

    update_data = book_update.dict(exclude_unset=True)
    for key, value in update_data.items():
        setattr(db_book, key, value)

    db_session.commit()
    db_session.refresh(db_book)
    return db_book

@app.delete("/books/{book_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_book(book_id: int, db_session: Session = Depends(get_db)):
    db_book = db_session.query(db.Book).filter(db.Book.id == book_id).first()
    if not db_book:
        raise HTTPException(status_code=404, detail="Book not found")
    db_session.delete(db_book)
    db_session.commit()
    return None

export type BookStatus = 'to-read' | 'reading' | 'done';

export interface Book {
  id: number;
  title: string;
  author: string;
  status: BookStatus;
}

export interface BookCreate {
  title: string;
  author: string;
  status: BookStatus;
}

export interface BookUpdate {
  title?: string;
  author?: string;
  status?: BookStatus;
}

import React, { useState, useEffect } from 'react';
import { Book, BookStatus, BookCreate } from './types';

const API_URL = 'http://localhost:8000';

export default function App() {
  const [books, setBooks] = useState<Book[]>([]);
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [status, setStatus] = useState<BookStatus>('to-read');
  const [filterStatus, setFilterStatus] = useState<BookStatus | 'all'>('all');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Fetch all books
  const fetchBooks = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`${API_URL}/books`);
      if (!response.ok) {
        throw new Error('Failed to fetch books');
      }
      const data = await response.json();
      setBooks(data);
    } catch (err: any) {
      setError(err.message || 'Qualcosa è andato storto');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchBooks();
  }, []);

  // Handle adding a new book
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || !author.trim()) return;

    setError(null);
    const newBook: BookCreate = {
      title: title.trim(),
      author: author.trim(),
      status
    };

    try {
      const response = await fetch(`${API_URL}/books`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(newBook),
      });

      if (!response.ok) {
        throw new Error('Impossibile aggiungere il libro');
      }

      const createdBook = await response.json();
      setBooks((prev) => [...prev, createdBook]);
      setTitle('');
      setAuthor('');
      setStatus('to-read');
    } catch (err: any) {
      setError(err.message || 'Errore durante la creazione del libro');
    }
  };

  // Handle changing status
  const handleStatusChange = async (id: number, newStatus: BookStatus) => {
    setError(null);
    try {
      const response = await fetch(`${API_URL}/books/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ status: newStatus }),
      });

      if (!response.ok) {
        throw new Error('Impossibile aggiornare lo stato del libro');
      }

      const updatedBook = await response.json();
      setBooks((prev) =>
        prev.map((book) => (book.id === id ? updatedBook : book))
      );
    } catch (err: any) {
      setError(err.message || 'Errore durante l\'aggiornamento dello stato');
    }
  };

  // Handle deleting a book
  const handleDelete = async (id: number) => {
    if (!confirm('Sei sicuro di voler eliminare questo libro?')) return;

    setError(null);
    try {
      const response = await fetch(`${API_URL}/books/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error('Impossibile eliminare il libro');
      }

      setBooks((prev) => prev.filter((book) => book.id !== id));
    } catch (err: any) {
      setError(err.message || 'Errore durante l\'eliminazione del libro');
    }
  };

  const filteredBooks = books.filter((book) => {
    if (filterStatus === 'all') return true;
    return book.status === filterStatus;
  });

  return (
    <div className="container">
      <header>
        <h1>📚 Il mio Book Tracker</h1>
        <p className="subtitle">Gestisci e traccia i libri che leggi in locale</p>
      </header>

      <main className="content">
        <section className="form-section">
          <h2>Aggiungi un nuovo libro</h2>
          <form onSubmit={handleSubmit} className="book-form">
            <div className="form-group">
              <label htmlFor="title">Titolo</label>
              <input
                id="title"
                type="text"
                placeholder="E.g. Il signore degli anelli"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                required
              />
            </div>

            <div className="form-group">
              <label htmlFor="author">Autore</label>
              <input
                id="author"
                type="text"
                placeholder="E.g. J.R.R. Tolkien"
                value={author}
                onChange={(e) => setAuthor(e.target.value)}
                required
              />
            </div>

            <div className="form-group">
              <label htmlFor="status">Stato di lettura</label>
              <select
                id="status"
                value={status}
                onChange={(e) => setStatus(e.target.value as BookStatus)}
              >
                <option value="to-read">Da leggere (To Read)</option>
                <option value="reading">In lettura (Reading)</option>
                <option value="done">Completato (Done)</option>
              </select>
            </div>

            <button type="submit" className="btn-primary">Aggiungi Libro</button>
          </form>
        </section>

        <section className="list-section">
          <div className="list-header">
            <h2>I Miei Libri ({filteredBooks.length})</h2>
            <div className="filter-controls">
              <label htmlFor="filter">Filtra per stato: </label>
              <select
                id="filter"
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value as BookStatus | 'all')}
              >
                <option value="all">Tutti</option>
                <option value="to-read">Da leggere</option>
                <option value="reading">In lettura</option>
                <option value="done">Completati</option>
              </select>
            </div>
          </div>

          {error && <div className="error-message">{error}</div>}

          {loading ? (
            <p className="loading">Caricamento libri...</p>
          ) : filteredBooks.length === 0 ? (
            <p className="empty-message">Nessun libro trovato. Inizia ad aggiungerne uno!</p>
          ) : (
            <div className="books-grid">
              {filteredBooks.map((book) => (
                <div key={book.id} className={`book-card card-status-${book.status}`}>
                  <div className="book-info">
                    <h3 className="book-title">{book.title}</h3>
                    <p className="book-author">di {book.author}</p>
                  </div>
                  <div className="book-actions">
                    <div className="status-selector">
                      <label htmlFor={`status-${book.id}`}>Stato:</label>
                      <select
                        id={`status-${book.id}`}
                        value={book.status}
                        onChange={(e) => handleStatusChange(book.id, e.target.value as BookStatus)}
                      >
                        <option value="to-read">Da leggere</option>
                        <option value="reading">In lettura</option>
                        <option value="done">Completato</option>
                      </select>
                    </div>
                    <button
                      onClick={() => handleDelete(book.id)}
                      className="btn-danger"
                      title="Elimina"
                    >
                      Elimina
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </main>
    </div>
  );
}

:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --border-color: #e2e8f0;

  --to-read-color: #cbd5e1;
  --reading-color: #fef08a;
  --done-color: #bbf7d0;

  --to-read-border: #94a3b8;
  --reading-border: #facc15;
  --done-border: #4ade80;

  --danger-color: #ef4444;
  --danger-hover: #dc2626;

  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;
  background-color: var(--bg-color);
  color: var(--text-main);
}

body {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

header {
  text-align: center;
  margin-bottom: 3rem;
}

h1 {
  font-size: 2.5rem;
  margin: 0 0 0.5rem 0;
  color: #1e293b;
}

.subtitle {
  font-size: 1.1rem;
  color: var(--text-muted);
  margin: 0;
}

.content {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2.5rem;
}

@media (min-width: 800px) {
  .content {
    grid-template-columns: 350px 1fr;
  }
}

/* Sections Layout */
.form-section, .list-section {
  background: var(--card-bg);
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  padding: 1.5rem;
}

h2 {
  font-size: 1.3rem;
  margin-top: 0;
  margin-bottom: 1.5rem;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 0.5rem;
  color: #1e293b;
}

/* Book Form styles */
.book-form {
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-group label {
  font-weight: 500;
  font-size: 0.9rem;
  color: #475569;
}

.form-group input, 
.form-group select,
.filter-controls select,
.status-selector select {
  font-family: inherit;
  font-size: 0.95rem;
  padding: 0.6rem 0.8rem;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background-color: #fff;
  color: var(--text-main);
  outline: none;
  transition: border-color 0.2s;
}

.form-group input:focus, 
.form-group select:focus {
  border-color: var(--primary-color);
}

.btn-primary {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: white;
  background-color: var(--primary-color);
  border: none;
  border-radius: 6px;
  padding: 0.75rem auto;
  height: 42px;
  cursor: pointer;
  transition: background-color 0.2s;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

/* List section & filters */
.list-header {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.5rem;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 0.5rem;
}

@media (min-width: 600px) {
  .list-header {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.list-header h2 {
  border-bottom: none;
  margin: 0;
  padding: 0;
}

.filter-controls {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.filter-controls label {
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* Grid layout for books */
.books-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
}

@media (min-width: 1000px) {
  .books-grid {
    grid-template-columns: 1fr 1fr;
  }
}

.book-card {
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 1.2rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 1rem;
  transition: transform 0.2s, box-shadow 0.2s;
}

.book-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px -2px rgb(0 0 0 / 0.05);
}

.book-title {
  margin: 0 0 0.2rem 0;
  font-size: 1.15rem;
  font-weight: 600;
  color: #1e293b;
}

.book-author {
  margin: 0;
  font-size: 0.95rem;
  color: var(--text-muted);
}

.book-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  border-top: 1px solid #f1f5f9;
  padding-top: 0.8rem;
}

.status-selector {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.status-selector label {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.status-selector select {
  padding: 0.35rem 0.6rem;
  font-size: 0.85rem;
}

.btn-danger {
  font-family: inherit;
  font-size: 0.85rem;
  color: var(--danger-color);
  background: transparent;
  border: 1px solid var(--danger-color);
  border-radius: 4px;
  padding: 0.35rem 0.6rem;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-danger:hover {
  color: white;
  background-color: var(--danger-color);
}

/* Card Status Accent Borders */
.card-status-to-read {
  border-left: 5px solid var(--to-read-border);
}

.card-status-reading {
  border-left: 5px solid var(--reading-border);
  background-color: #fefcf0;
}

.card-status-done {
  border-left: 5px solid var(--done-border);
  background-color: #fcfdf9;
}

/* Utilities */
.error-message {
  background-color: #fee2e2;
  color: #991b1b;
  padding: 0.75rem 1rem;
  border-radius: 6px;
  margin-bottom: 1rem;
  font-size: 0.9rem;
}

.empty-message {
  text-align: center;
  color: var(--text-muted);
  font-style: italic;
  padding: 2rem 0;
}

.loading {
  text-align: center;
  color: var(--text-muted);
}

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

// https://vite.dev/config/
export default defineConfig({
  plugins: [react()],
